export type SlackInfo = { connected: boolean, 
/**
 * Who the token belongs to, once checked since the start.
 */
identity: SlackIdentity | null, };

/**
 * A Slack status to set.
 */
export type SlackStatus = { 
/**
 * The emoji and text in Slack stay as they are.
 */
keepStatus: boolean, emoji: string, text: string, presence: Presence, };

/**
 * From and to as fractions of the timeline's width, 0 to 1.
 */
export type Span = { from: number, to: number, };

export type Status = "working" | "break" | "off";

/**
 * The payload of `status_changed`.
 */
export type StatusChanged = { 
/**
 * `None`: the day's first status.
 */
previous: Status | null, next: Status, 
/**
 * The day's first Working.
 */
first: boolean, 
/**
 * `HH:MM`
 */
since: string, 
/**
 * The channel message as confirmed in the overlay; empty sends none.
 */
message: string, 
/**
 * Going Off through the end-of-day check.
 */
endOfDay: EndOfDayAnswer | null, 
/**
 * The message already went out as the end of the end-of-day reply.
 */
messageSent: boolean, };

/**
 * One value per status.
 */
export type StatusMap<T> = { working: T, break: T, off: T, };

/**
 * The channel message per status.
 */
export type StatusMessages = { working: string, 
/**
 * The day's first Working; empty: the same as `working`.
 */
firstWorking: string, break: string, off: string, };

/**
 * The reply to `status`.
 */
export type StatusReport = { version: string, windowVisible: boolean, };

/**
 * The status overlay's session args.
 */
export type StatusRequest = { 
/**
 * Picked when the overlay opens.
 */
status: Status, 
/**
 * Today's status; `None` before the first one.
 */
current: Status | null, 
/**
 * The message each status suggests.
 */
messages: StatusMap<string>, 
/**
 * `None` when going Off asks nothing first.
 */
endOfDay: EndOfDayCheck | null, 
/**
 * Going Off asks for the end-of-day list first (the focus list goes to Slack, once a day).
 */
endOfDayList: boolean, };

/**
 * "An absence starts within `hours`": the enabled rule with the fewest hours that reaches it wins.
 */
export type StatusRule = { hours: number, enabled: boolean, 
/**
 * Text placeholders: `{when}` `{start}` `{end}` `{startDate}` `{endDate}` `{tz}`.
 */
slack: SlackStatus, };

export type StatusRules = { 
/**
 * Sorted by hours.
 */
rules: Array<StatusRule>, 
/**
 * Events with one of these titles are absences (e.g. "Out of office").
 */
absenceTitles: Array<string>, 
/**
 * Busy events at least this long are absences too (manually blocked days).
 */
minBusyHours: number, 
/**
 * After times, e.g. CEST; empty: the Mac's time zone abbreviation.
 */
tzLabel: string, };

/**
 * A piece of a shown text; `hit` pieces are highlighted.
 */
export type TextPart = { text: string, hit: boolean, };

/**
 * The size of all text. The frontend maps each step to its pixel sizes (`TEXT_SIZES` in `src/api/types.ts`).
 */
export type TextSize = "small" | "medium" | "large";

/**
 * A daily window from `from` to `to` (`HH:MM`; empty: the end of the day; before `from`: past
 * midnight).
 */
export type TimeWindow = { from: string, to: string, };

/**
 * The hours the day timeline shows, `first_hour` before `last_hour`.
 */
export type Timeline = { firstHour: number, lastHour: number, };

export type TimelineBlock = { 
/**
 * The event row's key.
 */
key: string, span: Span, 
/**
 * "09:00–09:30 Standup".
 */
label: string, past: boolean, 
/**
 * Another event runs up to or into its start.
 */
follows: boolean, };

export type TimelineHour = { 
/**
 * "09".
 */
label: string, at: number, 
/**
 * Every hour has a tick; labels skip hours so they never crowd.
 */
labeled: boolean, };

/**
 * When a routine or journal group is due, and when it opens by itself.
 */
export type Timing = { 
/**
 * Reminded in the Daybook window while due and not done; `None`: never due.
 */
due: TimeWindow | null, 
/**
 * Opens once a day when the due time starts (or later within it).
 */
openWhenDue: boolean, openOn: Array<OpenEvent>, };

export type TodoGroup = { label: string, todos: Array<OpenTodo>, };

export type TodoSpan = "today" | "week" | "month" | "all";

/**
 * The tools of the rail, the Daybook window's sidebar and the menu-bar menu.
 */
export type ToolId = "context" | "status" | "activity" | "call" | "separator1" | "journal" | "hub" | "search" | "jira" | "quickNotes" | "separator2" | "links" | "projects" | "music";

/**
 * Where a tool shows; the menu-bar menu always shows every tool.
 */
export type ToolPlacement = { id: ToolId, rail: boolean, 
/**
 * The Daybook window's sidebar; never for the Daybook tool (`Hub`) itself.
 */
window: boolean, };

export type ToolRow = { id: ToolId, title: string, 
/**
 * What a click runs; `None` for a row that only tells (the call).
 */
command: string | null, 
/**
 * The global shortcut, in Settings notation (`ctrl+alt+cmd+f`).
 */
shortcut: string | null, 
/**
 * Shown after the title, e.g. the time the status was set.
 */
detail: string | null, 
/**
 * Shown in the context's colour.
 */
accent: boolean, enabled: boolean, };

export type TopicRow = { topic: NoteSectionRef, 
/**
 * Not in the note yet; opening it adds it.
 */
create: boolean, };

export type UiState = { sidebarHidden: boolean, 
/**
 * The Daybook window's right column.
 */
inspectorHidden: boolean, 
/**
 * In px.
 */
sidebarWidth: number, 
/**
 * Splitter positions by pane id, in px.
 */
paneSizes: { [key in string]: number }, 
/**
 * The board lists only today's events that aren't over.
 */
hidePastEvents: boolean, 
/**
 * The labels of the inspector's todo groups that are folded away.
 */
collapsedTodoGroups: Array<string>, };

export type Vault = { path: string | null, 
/**
 * The name the Obsidian CLI knows the vault by.
 */
name: string, 
/**
 * Overrides the Obsidian CLI lookup; empty: find it automatically.
 */
obsidianCliPath: string, };

/**
 * Where the daily notes are and whether today's note and the Obsidian CLI were found.
 */
export type VaultInfo = { 
/**
 * `None` without a vault.
 */
dailyNotes: DailyNoteFormat | null, todayNote: string | null, todayNoteExists: boolean, obsidianCli: string | null, };

/**
 * On `days` (0 = Sunday; empty: every day) from `from` to `to` (`HH:MM`; a `to` before `from` runs
 * past midnight).
 */
export type WorkHours = { days: Array<number>, from: string, to: string, };

export type WriteOutcome = "written" | "unchanged" | "queued";
